(slug,title,content,summary,mood,category,published,is_approved,metadata)
values('zikr-story-05','الخطأ الذي لم يخفه المحرر','اكتشف محمود بعد نشر مقال أن رابط المصدر في آخره يقود إلى صفحة مختلفة. كان يستطيع تجاهل الأمر لأن معظم القراء لن يلاحظوا. لكنه أوقف المشاركة، أصلح الرابط، وأضاف تنبيهًا صغيرًا يوضح التصحيح.

سأله زميله: «لماذا تعلن الخطأ؟» أجابه: «لأن الثقة لا تعني ألا نخطئ؛ تعني ألا نخفي الخطأ عندما نكتشفه». أصبحت العبارة قاعدة في فريق التحرير، وصار لكل مادة سجل مراجعة بدل الاعتماد على الذاكرة.

القصة متخيلة، وتتناول ثقافة الجودة والشفافية في العمل التحريري.','قصة عن الشجاعة المهنية في تصحيح المحتوى.','المسؤولية','psychological',true,true,'{"fictional":true,"editorial":true,"not_historical_claim":true,"reviewed_at":"2026-09-19T01:45:17.855Z"}') on conflict (slug) do nothing;
insert into public.stories
(slug,title,content,summary,mood,category,published,is_approved,metadata)
values('zikr-story-06','مقعد الجار','كانت الشقة في آخر الممر تسكنها أسرة جديدة لا يعرفها أحد جيدًا. لاحظ كريم أن الأب يحمل أغراضه وحده كل مساء. في يوم ممطر نزل وساعده عشر دقائق، ثم عاد دون تصوير أو منشور.

بعد أسابيع صار سكان العمارة يتبادلون المساعدة في أشياء صغيرة: إصلاح مصباح، توصيل غرض، أو سؤال عن مريض. لم يكن هناك مشروع رسمي، فقط عادة جديدة بدأت من شخص قرر أن يرى من حوله.

القصة متخيلة وتركز على أثر الأعمال الصغيرة في بناء المجتمع.','قصة عن مساعدة لا تحتاج إلى إعلان.','الإحسان','psychological',true,true,'{"fictional":true,"editorial":true,"not_historical_claim":true,"reviewed_at":"2026-09-19T01:45:17.855Z"}') on conflict (slug) do nothing;
insert into public.stories
(slug,title,content,summary,mood,category,published,is_approved,metadata)
values('zikr-story-07','حين أغلق الهاتف','قبل الامتحان بأسبوع، كان فادي يفتح هاتفه «لدقيقة» فيضيع نصف ساعة. قرر أن يضع الهاتف خارج الغرفة أثناء جلسة المذاكرة. في البداية شعر بالفراغ، ثم بدأ التركيز يعود.

بعد أيام اكتشف أن أصعب خطوة لم تكن إغلاق التطبيق، بل أن يصنع بيئة لا تحتاج فيها إرادته إلى حرب كل خمس دقائق. جعل الإشعارات محدودة، ووضع وقتًا واضحًا للترفيه، فصار هاتفه أداة يستخدمها بدل أن تستخدمه هي.

القصة متخيلة وهدفها تقديم حل سلوكي بسيط.','قصة عن استعادة التركيز.','الانضباط الرقمي','psychological',true,true,'{"fictional":true,"editorial":true,"not_historical_claim":true,"reviewed_at":"2026-09-19T01:45:17.855Z"}') on conflict (slug) do nothing;
insert into public.stories
(slug,title,content,summary,mood,category,published,is_approved,metadata)
values('zikr-story-08','صندوق الأسئلة','في درس قصير سأل آدم عن معنى كلمة لم يفهمها. ضحك طفلان، فصمت. لاحظ المعلم صمته وقال: «السؤال الجيد يوفر على عشرات الناس سنوات من الخلط». بعد الدرس عاد آدم وكتب أسئلته في دفتر صغير.

مع الوقت صار الأطفال يضعون أسئلتهم في صندوق، ويجيب عنها المعلم من المصادر الموثوقة أو يعتذر عندما يحتاج إلى البحث. تعلم آدم أن عدم معرفة الجواب ليس مشكلة؛ المشكلة أن نخترع جوابًا حتى لا نبدو غير عارفين.

القصة متخيلة وتشجع على طلب العلم والتثبت.','قصة عن طفل يتعلم أن السؤال ليس عيبًا.','طلب العلم','psychological',true,true,'{"fictional":true,"editorial":true,"not_historical_claim":true,"reviewed_at":"2026-09-19T01:45:17.855Z"}') on conflict (slug) do nothing;
insert into public.stories
(slug,title,content,summary,mood,category,published,is_approved,metadata)
values('zikr-story-09','حقيبة الماء','في نزهة عائلية، لاحظت ليان أن الجميع يشتري زجاجات كثيرة ثم يترك بعضها. اقترحت على الأسرة أن يحمل كل واحد زجاجة قابلة لإعادة الاستخدام. لم تتغير المدينة بسبب قرارهم الصغير، لكن الأطفال بدأوا ينتبهون إلى أشياء أخرى يمكن تقليل هدرها.

في نهاية الأسبوع وضعوا ثلاث قواعد منزلية بسيطة: لا تترك الماء مفتوحًا بلا حاجة، خذ ما تحتاجه من الطعام، وأعد استخدام ما يصلح. صار الأطفال يتنافسون في اكتشاف الهدر بدل التنافس في شراء الأشياء.

القصة متخيلة، وهدفها تحويل الوعي البيئي إلى سلوك.','قصة عن تحويل الرحمة إلى عادة أسرية.','المبادرة','psychological',true,true,'{"fictional":true,"editorial":true,"not_historical_claim":true,"reviewed_at":"2026-09-19T01:45:17.855Z"}') on conflict (slug) do nothing;
insert into public.kids_content
(title_ar,slug,content_ar,type,age_group,title_en,content_en,quiz_data,summary_ar,summary_en,age_min,age_max,published,is_active,featured,facebook_share_enabled,likes,shares,metadata)
values('آداب الصلاة للصغار','zikr-kids-01','قبل الصلاة نستعد بهدوء ونحافظ على المكان ونحاول التركيز. ليس المطلوب أن يكون الطفل كاملًا من أول مرة؛ المطلوب أن يتعلم خطوة جديدة كل مرة. جربوا اليوم ثلاث عادات: غسل اليدين والوجه عند الوضوء بهدوء، إغلاق المشتتات، والوقوف في مكان مرتب. بعد الصلاة اسأل طفلك: ما الشيء الذي ساعدك على التركيز؟','lesson','6-8','Prayer Manners for Kids','What helped you focus during prayer?','[{"question":"آداب الصلاة للصغار","choices":["أحاول","أطلب المساعدة","أفكر أولًا"],"answer":0}]','قبل الصلاة نستعد بهدوء ونحافظ على المكان ونحاول التركيز. ليس المطلوب أن يكون الطفل كاملًا من أول مرة؛ المطلوب أن يتعلم خطوة جديدة كل مرة. جربوا اليوم ثلاث عادات: غسل اليدين والوجه ','What helped you focus during prayer?',6,8,true,true,false,true,0,0,'{"original":true,"educational":true,"reviewed_at":"2026-09-19T01:45:17.855Z"}') on conflict (slug) do nothing;
insert into public.kids_content
(title_ar,slug,content_ar,type,age_group,title_en,content_en,quiz_data,summary_ar,summary_en,age_min,age_max,published,is_active,featured,facebook_share_enabled,likes,shares,metadata)
values('قصة الصدق','zikr-kids-02','وجد سامر لعبة في ساحة المدرسة ولم يعرف صاحبها. فكر أن يحتفظ بها، لكنه قال للمعلم الحقيقة ووضع اللعبة في صندوق المفقودات. في اليوم التالي وجدها طفل يبحث عنها وفرح بها. تعلم سامر أن الصدق قد يجعلنا نترك شيئًا نحبه، لكنه يجعلنا نثق بأنفسنا والآخرين. نشاط اليوم: احكِ موقفًا كان فيه الصدق صعبًا ثم ناقش لماذا اخترته.','story','6-8','The Honesty Story','Tell a time when honesty was difficult.','[{"question":"قصة الصدق","choices":["أحاول","أطلب المساعدة","أفكر أولًا"],"answer":0}]','وجد سامر لعبة في ساحة المدرسة ولم يعرف صاحبها. فكر أن يحتفظ بها، لكنه قال للمعلم الحقيقة ووضع اللعبة في صندوق المفقودات. في اليوم التالي وجدها طفل يبحث عنها وفرح بها. تعلم سامر أن ','Tell a time when honesty was difficult.',6,8,true,true,false,true,0,0,'{"original":true,"educational":true,"reviewed_at":"2026-09-19T01:45:17.855Z"}') on conflict (slug) do nothing;
insert into public.kids_content
(title_ar,slug,content_ar,type,age_group,title_en,content_en,quiz_data,summary_ar,summary_en,age_min,age_max,published,is_active,featured,facebook_share_enabled,likes,shares,metadata)
values('مهمة الأمانة','zikr-kids-03','اختر مهمة منزلية صغيرة لا تحتاج أن يذكرك بها أحد: ترتيب الكتب، وضع الحذاء في مكانه، أو إطعام حيوان أليف بإشراف الأسرة. سجّلها في بطاقة اسمها «مهمة الأمانة». الهدف ليس الكمال، بل أن يعرف الطفل أن الناس يستطيعون الاعتماد عليه.','activity','6-8','The Trust Mission','Choose one small responsibility and complete it without reminders.','[{"question":"مهمة الأمانة","choices":["أحاول","أطلب المساعدة","أفكر أولًا"],"answer":0}]','اختر مهمة منزلية صغيرة لا تحتاج أن يذكرك بها أحد: ترتيب الكتب، وضع الحذاء في مكانه، أو إطعام حيوان أليف بإشراف الأسرة. سجّلها في بطاقة اسمها «مهمة الأمانة». الهدف ليس الكمال، بل أن','Choose one small responsibility and complete it without reminders.',6,8,true,true,false,true,0,0,'{"original":true,"educational":true,"reviewed_at":"2026-09-19T01:45:17.855Z"}') on conflict (slug) do nothing;
insert into public.kids_content
(title_ar,slug,content_ar,type,age_group,title_en,content_en,quiz_data,summary_ar,summary_en,age_min,age_max,published,is_active,featured,facebook_share_enabled,likes,shares,metadata)
values('مغامرة المسجد','zikr-kids-04','في طريقه إلى المسجد، لاحظ مازن أن شخصًا يحتاج إلى معرفة مكان الوضوء. ساعده ثم دخل بهدوء. بعد الصلاة أعاد حذاءه إلى مكانه ولم يترك ورقة في الأرض. كانت المغامرة قصيرة، لكنها علمته أن آداب المسجد تبدأ من الطريق وتستمر بعد الصلاة. نشاط: اكتب أو ارسم ثلاث طرق تجعل المسجد أجمل لمن يأتي بعدك.','story','6-8','Mosque Adventure','Draw three ways to keep the mosque welcoming.','[{"question":"مغامرة المسجد","choices":["أحاول","أطلب المساعدة","أفكر أولًا"],"answer":0}]','في طريقه إلى المسجد، لاحظ مازن أن شخصًا يحتاج إلى معرفة مكان الوضوء. ساعده ثم دخل بهدوء. بعد الصلاة أعاد حذاءه إلى مكانه ولم يترك ورقة في الأرض. كانت المغامرة قصيرة، لكنها علمته أن','Draw three ways to keep the mosque welcoming.',6,8,true,true,false,true,0,0,'{"original":true,"educational":true,"reviewed_at":"2026-09-19T01:45:17.855Z"}') on conflict (slug) do nothing;
insert into public.kids_content
(title_ar,slug,content_ar,type,age_group,title_en,content_en,quiz_data,summary_ar,summary_en,age_min,age_max,published,is_active,featured,facebook_share_enabled,likes,shares,metadata)
values('طريق الذكر','zikr-kids-05','حوّل الذكر إلى مسار ممتع غير قائم على المنافسة. ضع ثلاث محطات في البيت، وعند كل محطة كلمة طيبة أو دعاء مأثور يراجعه الطفل مع والده. بعد انتهاء الجولة، اختاروا محطة واحدة فقط لتصبح عادة يومية.','activity','6-8','The Dhikr Path','Create three calm stations for a family remembrance routine.','[{"question":"طريق الذكر","choices":["أحاول","أطلب المساعدة","أفكر أولًا"],"answer":0}]','حوّل الذكر إلى مسار ممتع غير قائم على المنافسة. ضع ثلاث محطات في البيت، وعند كل محطة كلمة طيبة أو دعاء مأثور يراجعه الطفل مع والده. بعد انتهاء الجولة، اختاروا محطة واحدة فقط لتصبح ','Create three calm stations for a family remembrance routine.',6,8,true,true,false,true,0,0,'{"original":true,"educational":true,"reviewed_at":"2026-09-19T01:45:17.855Z"}') on conflict (slug) do nothing;
insert into public.kids_content
(title_ar,slug,content_ar,type,age_group,title_en,content_en,quiz_data,summary_ar,summary_en,age_min,age_max,published,is_active,featured,facebook_share_enabled,likes,shares,metadata)
values('قفزة ذِكر','zikr-kids-06','لعبة حركة بسيطة: يختار الأب أو المعلم كلمة ذكر صحيحة ومأثورة يعرفها الطفل، ثم يتحرك الطفل خطوة مع كل ترديد حتى يصل إلى عدد متفق عليه يناسب عمره. احرص على أن يكون الهدف الفهم والحب للذكر، لا الضغط على الطفل أو جعله يشعر بالفشل.','activity','6-8','Dhikr Jump','Make the game about joy and understanding, not pressure.','[{"question":"قفزة ذِكر","choices":["أحاول","أطلب المساعدة","أفكر أولًا"],"answer":0}]','لعبة حركة بسيطة: يختار الأب أو المعلم كلمة ذكر صحيحة ومأثورة يعرفها الطفل، ثم يتحرك الطفل خطوة مع كل ترديد حتى يصل إلى عدد متفق عليه يناسب عمره. احرص على أن يكون الهدف الفهم والحب ','Make the game about joy and understanding, not pressure.',6,8,true,true,false,true,0,0,'{"original":true,"educational":true,"reviewed_at":"2026-09-19T01:45:17.855Z"}') on conflict (slug) do nothing;
insert into public.kids_content
(title_ar,slug,content_ar,type,age_group,title_en,content_en,quiz_data,summary_ar,summary_en,age_min,age_max,published,is_active,featured,facebook_share_enabled,likes,shares,metadata)
values('أعمال الخير','zikr-kids-07','اقترح على الطفل ثلاث أعمال سهلة: مساعدة أحد أفراد الأسرة، وضع لعبة في مكانها، وكلمة طيبة لصديق. اجعل الطفل يختار واحدًا وينفذه ثم يخبرك كيف شعر الطرف الآخر. لا تحول العمل إلى جائزة مالية؛ ركز على أثر الخير.','activity','3-5','Little Acts of Good','Choose one kind action and talk about its effect.','[{"question":"أعمال الخير","choices":["أحاول","أطلب المساعدة","أفكر أولًا"],"answer":0}]','اقترح على الطفل ثلاث أعمال سهلة: مساعدة أحد أفراد الأسرة، وضع لعبة في مكانها، وكلمة طيبة لصديق. اجعل الطفل يختار واحدًا وينفذه ثم يخبرك كيف شعر الطرف الآخر. لا تحول العمل إلى جائزة','Choose one kind action and talk about its effect.',3,5,true,true,false,true,0,0,'{"original":true,"educational":true,"reviewed_at":"2026-09-19T01:45:17.855Z"}') on conflict (slug) do nothing;
