(title_ar,slug,content_ar,type,age_group,title_en,content_en,quiz_data,summary_ar,summary_en,age_min,age_max,published,is_active,featured,facebook_share_enabled,likes,shares,metadata)
values('ترتيب المكان','zikr-kids-08','بعد اللعب، اختر خمس قطع فقط لإعادتها إلى مكانها. علّم الطفل أن النظافة مسؤولية مشتركة وليست مهمة شخص واحد. يمكن أن يستخدم مؤقتًا لدقيقتين ثم يتوقف حتى لا تتحول المهمة إلى عبء. في النهاية اسأله: كيف تغير المكان عندما تعاونّا؟','lesson','6-8','Tidy the Place','Put five things back in place and notice the difference.','[{"question":"ترتيب المكان","choices":["أحاول","أطلب المساعدة","أفكر أولًا"],"answer":0}]','بعد اللعب، اختر خمس قطع فقط لإعادتها إلى مكانها. علّم الطفل أن النظافة مسؤولية مشتركة وليست مهمة شخص واحد. يمكن أن يستخدم مؤقتًا لدقيقتين ثم يتوقف حتى لا تتحول المهمة إلى عبء. في ا','Put five things back in place and notice the difference.',6,8,true,true,false,true,0,0,'{"original":true,"educational":true,"reviewed_at":"2026-09-19T01:45:17.855Z"}') on conflict (slug) do nothing;
