(title_ar,slug,content_ar,type,age_group,title_en,content_en,quiz_data,summary_ar,summary_en,age_min,age_max,published,is_active,featured,facebook_share_enabled,likes,shares,metadata)
values('لغز الآية','zikr-kids-09','اقرأ آية قصيرة من مصدر موثوق ثم اطلب من الطفل تحديد فكرة واحدة واضحة منها بكلماته، دون حفظ نص طويل. بعد ذلك ناقش كيف يمكن تطبيق الفكرة في البيت أو المدرسة. النشاط يدرب على الفهم والتدبر بدل جمع الإجابات السريعة.','activity','9-12','Verse Puzzle','Explain one lesson from a short verse in your own words.','[{"question":"لغز الآية","choices":["أحاول","أطلب المساعدة","أفكر أولًا"],"answer":0}]','اقرأ آية قصيرة من مصدر موثوق ثم اطلب من الطفل تحديد فكرة واحدة واضحة منها بكلماته، دون حفظ نص طويل. بعد ذلك ناقش كيف يمكن تطبيق الفكرة في البيت أو المدرسة. النشاط يدرب على الفهم وا','Explain one lesson from a short verse in your own words.',9,12,true,true,false,true,0,0,'{"original":true,"educational":true,"reviewed_at":"2026-09-19T01:45:17.855Z"}') on conflict (slug) do nothing;
insert into public.kids_content
(title_ar,slug,content_ar,type,age_group,title_en,content_en,quiz_data,summary_ar,summary_en,age_min,age_max,published,is_active,featured,facebook_share_enabled,likes,shares,metadata)
values('اختبار ذِكر','zikr-kids-10','اختبار قصير بثلاثة أسئلة: متى نحتاج إلى التثبت من معلومة؟ ما الفرق بين كلمة طيبة وسخرية؟ ولماذا نحافظ على وقت الصلاة؟ لا تجعل النتيجة أهم من الحوار. الطفل الذي يسأل سؤالًا جديدًا يحصل على نقطة فضول إضافية.','activity','6-8','Zikr Quiz','Three questions for reflection, not competition.','[{"question":"اختبار ذِكر","choices":["أحاول","أطلب المساعدة","أفكر أولًا"],"answer":0}]','اختبار قصير بثلاثة أسئلة: متى نحتاج إلى التثبت من معلومة؟ ما الفرق بين كلمة طيبة وسخرية؟ ولماذا نحافظ على وقت الصلاة؟ لا تجعل النتيجة أهم من الحوار. الطفل الذي يسأل سؤالًا جديدًا ي','Three questions for reflection, not competition.',6,8,true,true,false,true,0,0,'{"original":true,"educational":true,"reviewed_at":"2026-09-19T01:45:17.855Z"}') on conflict (slug) do nothing;
insert into public.kids_content
(title_ar,slug,content_ar,type,age_group,title_en,content_en,quiz_data,summary_ar,summary_en,age_min,age_max,published,is_active,featured,facebook_share_enabled,likes,shares,metadata)
values('كيف أعتذر؟','zikr-kids-11','الاعتذار الجيد يتكون من ثلاث خطوات: الاعتراف بالخطأ دون أعذار طويلة، بيان أنك فهمت أثره، ثم محاولة إصلاح ما يمكن إصلاحه. استخدم موقفًا بسيطًا من المدرسة أو البيت وتدرّب على الاعتذار بجملة واحدة واضحة.','lesson','9-12','How Do I Apologize?','Practice a clear apology with three simple steps.','[{"question":"كيف أعتذر؟","choices":["أحاول","أطلب المساعدة","أفكر أولًا"],"answer":0}]','الاعتذار الجيد يتكون من ثلاث خطوات: الاعتراف بالخطأ دون أعذار طويلة، بيان أنك فهمت أثره، ثم محاولة إصلاح ما يمكن إصلاحه. استخدم موقفًا بسيطًا من المدرسة أو البيت وتدرّب على الاعتذا','Practice a clear apology with three simple steps.',9,12,true,true,false,true,0,0,'{"original":true,"educational":true,"reviewed_at":"2026-09-19T01:45:17.855Z"}') on conflict (slug) do nothing;
insert into public.kids_content
(title_ar,slug,content_ar,type,age_group,title_en,content_en,quiz_data,summary_ar,summary_en,age_min,age_max,published,is_active,featured,facebook_share_enabled,likes,shares,metadata)
values('صديق يسمع','zikr-kids-12','جلس رائد مع صديقه الذي كان منزعجًا. حاول في البداية أن يعطيه نصيحة مباشرة، ثم توقف وسأله: «هل تريد مني أن أسمع فقط أم نبحث عن حل؟». شعر صديقه بالراحة لأن رائد فهم حاجته أولًا. نشاط اليوم: جرّب الاستماع لدقيقة كاملة دون مقاطعة.','story','6-8','A Friend Who Listens','Listen for one full minute before giving advice.','[{"question":"صديق يسمع","choices":["أحاول","أطلب المساعدة","أفكر أولًا"],"answer":0}]','جلس رائد مع صديقه الذي كان منزعجًا. حاول في البداية أن يعطيه نصيحة مباشرة، ثم توقف وسأله: «هل تريد مني أن أسمع فقط أم نبحث عن حل؟». شعر صديقه بالراحة لأن رائد فهم حاجته أولًا. نشاط','Listen for one full minute before giving advice.',6,8,true,true,false,true,0,0,'{"original":true,"educational":true,"reviewed_at":"2026-09-19T01:45:17.855Z"}') on conflict (slug) do nothing;
